/* Real GTK window -> shared MoonBit owner -> media worker integration.
 * SOURCE is the six-second 320x180 source generated by gst-media; OUTPUT is an
 * isolated fresh directory. No synthetic playback clock/document/video paint. */
#include <gtk/gtk.h>
#include <glib/gstdio.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "platform/linux/app/video_editor.h"
#include "platform/linux/graphics/shared_canvas.h"
#include "platform/linux/media/runtime.h"

static int failures, criticals;
static void check(gboolean passed, const char *message) {
    printf("%s %s\n", passed ? "PASS" : "FAIL", message); fflush(stdout);
    if (!passed) failures++;
}
static void log_critical(const gchar *domain, GLogLevelFlags level, const gchar *message, gpointer data) {
    (void)data; criticals++; g_log_default_handler(domain, level, message, NULL);
}
static const char *field(const char *json, const char *key) {
    char pattern[96]; g_snprintf(pattern, sizeof pattern, "\"%s\":", key);
    const char *at = json ? strstr(json, pattern) : NULL;
    if (!at) return NULL;
    at += strlen(pattern); while (*at == ' ' || *at == '\n') at++; return at;
}
static double number(const char *json, const char *key) {
    const char *at = field(json, key); return at ? g_ascii_strtod(at, NULL) : -1;
}
static gboolean flag(const char *json, const char *key) {
    const char *at = field(json, key); return at && !strncmp(at, "true", 4);
}
static void pump(unsigned milliseconds) {
    gint64 until = g_get_monotonic_time() + (gint64)milliseconds * 1000;
    do {
        while (g_main_context_iteration(NULL, FALSE)) {}
        if (g_get_monotonic_time() < until) g_usleep(1000);
    } while (g_get_monotonic_time() < until);
}
static gboolean settled(GtkWidget *window, double revision) {
    gint64 until = g_get_monotonic_time() + 45000000;
    do {
        pump(5);
        char *state = mc_linux_video_editor_state(window);
        gboolean ready = state && number(state, "revision") == revision &&
            flag(state, "mediaReady") && !flag(state, "dirty");
        mc_linux_video_editor_text_free(state);
        if (ready) return TRUE;
    } while (!gtk_widget_in_destruction(window) && g_get_monotonic_time() < until);
    char *state = mc_linux_video_editor_state(window);
    fprintf(stderr, "Window settle timeout: %s\n", state ? state : "no state");
    mc_linux_video_editor_text_free(state); return FALSE;
}
static gboolean wait_closed(void) {
    gint64 until = g_get_monotonic_time() + 45000000;
    while (mc_linux_video_editors_busy() && g_get_monotonic_time() < until) pump(5);
    return !mc_linux_video_editors_busy();
}
static gboolean wait_veto(void) {
    gint64 until = g_get_monotonic_time() + 15000000;
    do { pump(5); if (mc_linux_video_editors_busy() && !mc_linux_video_editors_closing()) return TRUE; }
    while (mc_linux_video_editors_busy() && g_get_monotonic_time() < until);
    return FALSE;
}
static gboolean retry_error(GtkWidget *window) {
    GList *tops = gtk_window_list_toplevels(); GtkWidget *dialog = NULL;
    for (GList *at = tops; at; at = at->next)
        if (GTK_IS_MESSAGE_DIALOG(at->data) && gtk_window_get_transient_for(GTK_WINDOW(at->data)) == GTK_WINDOW(window)) {
            dialog = g_object_ref(at->data); break;
        }
    g_list_free(tops); if (!dialog) return FALSE;
    gtk_dialog_response(GTK_DIALOG(dialog), GTK_RESPONSE_APPLY); g_object_unref(dialog); return TRUE;
}
static char *text(moonbit_string_t value) {
    char *out = g_utf16_to_utf8(value, Moonbit_array_length(value), NULL, NULL, NULL);
    moonbit_decref(value); return out;
}
static int semantic(int32_t frame, const char *id) {
    for (int i = 0; i < ui_frame_semantic_count(frame); i++) {
        char *name = text(ui_frame_semantic_text(frame, i, MC_UI_SEM_ID));
        gboolean match = !g_strcmp0(name, id); g_free(name); if (match) return i;
    }
    return -1;
}
static char *matching_id(GtkWidget *window, const char *prefix, gboolean skip_first) {
    int32_t frame = mc_linux_video_editor_frame_snapshot(window); char *result = NULL;
    for (int i = 0; i < ui_frame_semantic_count(frame); i++) {
        char *name = text(ui_frame_semantic_text(frame, i, MC_UI_SEM_ID));
        if (name && g_str_has_prefix(name, prefix)) {
            if (skip_first) skip_first = FALSE;
            else { result = name; break; }
        }
        g_free(name);
    }
    if (frame) ui_frame_close(frame); return result;
}
static gboolean point(GtkWidget *window, const char *id, double *x, double *y, double *width) {
    int32_t frame = mc_linux_video_editor_frame_snapshot(window); int index = semantic(frame, id);
    gboolean valid = index >= 0 && ui_frame_semantic_value(frame, index, MC_UI_SEM_ENABLED) == 1;
    if (valid) {
        double w = ui_frame_semantic_number(frame, index, MC_UI_SEM_WIDTH);
        *x = ui_frame_semantic_number(frame, index, MC_UI_SEM_X) + w / 2;
        *y = ui_frame_semantic_number(frame, index, MC_UI_SEM_Y) +
            ui_frame_semantic_number(frame, index, MC_UI_SEM_HEIGHT) / 2;
        if (width) *width = w;
    }
    if (frame) ui_frame_close(frame); return valid;
}
static GtkWidget *canvas(GtkWidget *window) { return gtk_bin_get_child(GTK_BIN(window)); }
static void pointer(GtkWidget *window, GdkEventType type, double x, double y) {
    GtkWidget *widget = canvas(window);
    GdkEvent *event = gdk_event_new(type); event->any.window = g_object_ref(gtk_widget_get_window(widget));
    event->any.send_event = TRUE;
    if (type == GDK_MOTION_NOTIFY) {
        event->motion.time = GDK_CURRENT_TIME; event->motion.x = x; event->motion.y = y;
        event->motion.state = GDK_BUTTON1_MASK;
    } else {
        event->button.time = GDK_CURRENT_TIME; event->button.x = x; event->button.y = y; event->button.button = 1;
        event->button.state = type == GDK_BUTTON_PRESS ? 0 : GDK_BUTTON1_MASK;
    }
    gdk_event_set_device(event, gdk_seat_get_pointer(gdk_display_get_default_seat(gtk_widget_get_display(widget))));
    gtk_widget_event(widget, event); gdk_event_free(event);
}
static gboolean click(GtkWidget *window, const char *id) {
    double x, y; if (!point(window, id, &x, &y, NULL)) return FALSE;
    pointer(window, GDK_BUTTON_PRESS, x, y); pointer(window, GDK_BUTTON_RELEASE, x, y); return TRUE;
}
static void key(GtkWidget *window, guint keyval, GdkModifierType modifiers) {
    GtkWidget *widget = canvas(window); gtk_widget_grab_focus(widget);
    GdkEvent *event = gdk_event_new(GDK_KEY_PRESS); event->key.window = g_object_ref(gtk_widget_get_window(widget));
    event->key.send_event = TRUE; event->key.time = GDK_CURRENT_TIME;
    event->key.keyval = keyval; event->key.state = modifiers;
    gdk_event_set_device(event, gdk_seat_get_keyboard(gdk_display_get_default_seat(gtk_widget_get_display(widget))));
    gtk_widget_event(widget, event); gdk_event_free(event);
}
static double revision(GtkWidget *window) {
    char *state = mc_linux_video_editor_state(window); double result = number(state, "revision");
    mc_linux_video_editor_text_free(state); return result;
}
static gboolean seek(GtkWidget *window, double milliseconds) {
    int32_t frame = mc_linux_video_editor_frame_snapshot(window); int index = semantic(frame, "playhead");
    double max = ui_frame_semantic_number(frame, index, MC_UI_SEM_MAX);
    gboolean valid = index >= 0 && max > 0 && milliseconds >= 0 && milliseconds <= max;
    double x = ui_frame_semantic_number(frame, index, MC_UI_SEM_X) +
        ui_frame_semantic_number(frame, index, MC_UI_SEM_WIDTH) * milliseconds / max;
    double y = ui_frame_semantic_number(frame, index, MC_UI_SEM_Y) +
        ui_frame_semantic_number(frame, index, MC_UI_SEM_HEIGHT) / 2;
    if (frame) ui_frame_close(frame);
    if (valid) { pointer(window, GDK_BUTTON_PRESS, x, y); pointer(window, GDK_BUTTON_RELEASE, x, y); }
    return valid;
}
static guint32 pixel(cairo_surface_t *surface, int x, int y) {
    unsigned char *row = cairo_image_surface_get_data(surface) + y * cairo_image_surface_get_stride(surface);
    return ((guint32 *)row)[x] & 0xffffff;
}
/* Invoke the actual realized GTK widget's draw signal. Samples are well inside
 * the fitted media image, away from letterbox, controls and the time barcode. */
static gboolean screenshot(GtkWidget *window, const char *path, gboolean black) {
    GtkWidget *widget = canvas(window); int width = gtk_widget_get_allocated_width(widget);
    int height = gtk_widget_get_allocated_height(widget);
    if (width <= 0 || height <= 0 || width > 8192 || height > 8192) return FALSE;
    int32_t frame = mc_linux_video_editor_frame_snapshot(window);
    double vx = ui_frame_video_rect(frame, MC_UI_RECT_X), vy = ui_frame_video_rect(frame, MC_UI_RECT_Y);
    double vw = ui_frame_video_rect(frame, MC_UI_RECT_WIDTH), vh = ui_frame_video_rect(frame, MC_UI_RECT_HEIGHT);
    if (frame) ui_frame_close(frame);
    if (vw <= 0 || vh <= 0) return FALSE;
    double scale = fmin(vw / 320.0, vh / 180.0);
    double origin_x = vx + (vw - 320 * scale) / 2, origin_y = vy + (vh - 180 * scale) / 2;
    cairo_surface_t *surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, width, height);
    cairo_t *cr = cairo_create(surface); gtk_widget_draw(widget, cr); cairo_surface_flush(surface);
    gboolean valid = TRUE;
    const double locations[][2] = {{80, 60}, {240, 60}, {80, 135}, {240, 135}};
    for (size_t i = 0; i < G_N_ELEMENTS(locations); i++) {
        guint32 value = pixel(surface, (int)(origin_x + locations[i][0] * scale), (int)(origin_y + locations[i][1] * scale));
        unsigned red = value >> 16, green = (value >> 8) & 255, blue = value & 255;
        unsigned brightest = MAX(red, MAX(green, blue)), darkest = MIN(red, MIN(green, blue));
        valid = valid && (black ? brightest < 10 : brightest > 100 && brightest - darkest > 80);
    }
    valid = cairo_status(cr) == CAIRO_STATUS_SUCCESS && valid;
    if (path) valid = cairo_surface_write_to_png(surface, path) == CAIRO_STATUS_SUCCESS && valid;
    cairo_destroy(cr); cairo_surface_destroy(surface); return valid;
}
static gboolean wait_pixels(GtkWidget *window, const char *path, gboolean black) {
    gint64 until = g_get_monotonic_time() + 15000000;
    do { pump(40); if (screenshot(window, NULL, black)) return screenshot(window, path, black); }
    while (g_get_monotonic_time() < until);
    return FALSE;
}
static char *hash(const char *path) {
    FILE *file = g_fopen(path, "rb"); if (!file) return NULL;
    GChecksum *checksum = g_checksum_new(G_CHECKSUM_SHA256); unsigned char bytes[16384]; size_t count;
    while ((count = fread(bytes, 1, sizeof bytes, file))) g_checksum_update(checksum, bytes, count);
    char *result = ferror(file) ? NULL : g_strdup(g_checksum_get_string(checksum));
    g_checksum_free(checksum); fclose(file); return result;
}
static gboolean count_draw(GtkWidget *widget, cairo_t *cr, gpointer data) {
    (void)widget; (void)cr; (*(unsigned *)data)++; return FALSE;
}
static gboolean waveform_visible(GtkWidget *window) {
    gint64 until = g_get_monotonic_time() + 15000000;
    do {
        pump(40); int32_t frame = mc_linux_video_editor_frame_snapshot(window);
        // 1024 decoded tone peaks produce several hundred two-pixel columns.
        // The ordinary controls/clip rectangles stay well below this count.
        gboolean ready = ui_frame_command_count(frame, MC_UI_LAYER_COMMANDS) > 300;
        int node = semantic(frame, "clip:a1");
        double x = ui_frame_semantic_number(frame, node, MC_UI_SEM_X);
        double y = ui_frame_semantic_number(frame, node, MC_UI_SEM_Y);
        double width = ui_frame_semantic_number(frame, node, MC_UI_SEM_WIDTH);
        double height = ui_frame_semantic_number(frame, node, MC_UI_SEM_HEIGHT);
        if (frame) ui_frame_close(frame);
        if (ready && node >= 0 && width > 200 && height > 35) {
            GtkWidget *widget = canvas(window);
            cairo_surface_t *surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32,
                gtk_widget_get_allocated_width(widget), gtk_widget_get_allocated_height(widget));
            cairo_t *cr = cairo_create(surface); gtk_widget_draw(widget, cr); cairo_surface_flush(surface);
            unsigned columns = 0;
            // Inspect actual painted audio pixels, not just a newly requested
            // host snapshot (which could hide a missing serial-triggered redraw).
            for (int column = (int)(x + width / 3); column < (int)(x + width * 2 / 3); column += 2) {
                guint32 peak = pixel(surface, column, (int)(y + height * .65));
                guint32 base = pixel(surface, column, (int)(y + height - 3));
                if (abs((int)(peak & 255) - (int)(base & 255)) > 20) columns++;
            }
            cairo_destroy(cr); cairo_surface_destroy(surface);
            if (columns > 50) return TRUE;
        }
    } while (g_get_monotonic_time() < until);
    return FALSE;
}

int main(int argc, char **argv) {
    char runtime_error[512];
    if (!mc_linux_media_runtime_init(runtime_error, sizeof runtime_error)) {
        fprintf(stderr, "%s\n", runtime_error); return 2;
    }
    if (argc != 3) { fprintf(stderr, "usage: linux-video-editor SOURCE OUTPUT_DIR\n"); return 2; }
    gtk_init(&argc, &argv); moonbit_init();
    const char *domains[] = {"GLib-GObject", "Gtk", "Gdk"}; guint handlers[G_N_ELEMENTS(domains)];
    for (size_t i = 0; i < G_N_ELEMENTS(domains); i++)
        handlers[i] = g_log_set_handler(domains[i], G_LOG_LEVEL_CRITICAL, log_critical, NULL);
    GtkApplication *application = gtk_application_new("com.moojicut.test.editor", G_APPLICATION_NON_UNIQUE);
    GError *error = NULL;
    if (!g_application_register(G_APPLICATION(application), NULL, &error)) {
        fprintf(stderr, "Cannot register GTK fixture: %s\n", error->message); g_error_free(error); return 2;
    }
    g_mkdir_with_parents(argv[2], 0700);
    char *draft = g_build_filename(argv[2], "edit-v2.json", NULL);
    char *image = g_build_filename(argv[2], "editor.png", NULL);
    char *gap_image = g_build_filename(argv[2], "gap.png", NULL);
    char *backup = g_build_filename(argv[2], "saved-draft.json", NULL);
    char *original = hash(argv[1]), *second = NULL, *gap = NULL;
    GtkWidget *window = NULL;
    if (g_file_test(draft, G_FILE_TEST_EXISTS)) { fprintf(stderr, "Expected a fresh output directory\n"); failures++; goto done; }
    window = mc_linux_video_editor_open_test(application, argv[1], draft, TRUE);
    if (window) g_object_ref(window); // fixture can safely query the retired widget after asynchronous close
    check(window && mc_linux_video_editors_busy(), "real GTK window retains asynchronous host ownership");
    if (!window || !settled(window, 0)) { check(FALSE, "initial probe and plan become ready"); goto done; }
    check(TRUE, "initial probe and plan become ready");
    check(wait_pixels(window, image, FALSE), "actual GTK draw paints decoded BGRA color quadrants with shared controls");
    check(click(window, "project-audio-toggle") && waveform_visible(window), "source audio analysis reaches the real timeline frame");
    pump(300);
    unsigned draws = 0; gulong draw_handler = g_signal_connect(canvas(window), "draw", G_CALLBACK(count_draw), &draws);
    pump(250); g_signal_handler_disconnect(canvas(window), draw_handler);
    check(draws == 0, "paused idle ticks do not rebuild and repaint the shared frame");
    check(click(window, "clip:v1") && seek(window, 3000) && wait_pixels(window, NULL, FALSE),
        "native clip selection and ruler input seek actual source pixels");
    if (!click(window, "project-split") || !settled(window, 1)) {
        check(FALSE, "split applies media and saves the authoritative draft"); goto done;
    }
    check(TRUE, "split applies media and saves the authoritative draft");
    second = matching_id(window, "clip:v", TRUE); double x, y;
    if (!second || !point(window, second, &x, &y, NULL)) { check(FALSE, "split exposes second clip"); goto done; }
    pointer(window, GDK_BUTTON_PRESS, x, y); pointer(window, GDK_MOTION_NOTIFY, x + 100, y);
    check(revision(window) == 1 && gtk_grab_get_current() == canvas(window), "body drag previews without committing and owns pointer capture");
    key(window, GDK_KEY_Escape, 0); pointer(window, GDK_BUTTON_RELEASE, x + 100, y);
    check(revision(window) == 1 && gtk_grab_get_current() != canvas(window), "Escape cancels drag and ignores the late pointer release");
    pointer(window, GDK_BUTTON_PRESS, x, y); pointer(window, GDK_MOTION_NOTIFY, x + 100, y);
    pointer(window, GDK_BUTTON_RELEASE, x + 100, y);
    gboolean moved = settled(window, 2); gap = matching_id(window, "gap:", FALSE);
    check(moved && gap, "real clip drag creates a gap through shared input, draft and media plan");
    long long gap_start = 0, gap_end = 0;
    if (gap && sscanf(gap, "gap:%lld:%lld", &gap_start, &gap_end) == 2 && gap_end > gap_start) {
        char *state = mc_linux_video_editor_state(window); const char *at = state; int linked = 0;
        while (at && (at = field(at, "startTicks"))) { if ((long long)g_ascii_strtod(at, NULL) == gap_end) linked++; at++; }
        check(linked >= 2, "video and associated audio move to the same absolute timeline position");
        mc_linux_video_editor_text_free(state);
        key(window, GDK_KEY_0, GDK_CONTROL_MASK);
        check(seek(window, (gap_start + gap_end) / 180.0) && wait_pixels(window, gap_image, TRUE),
            "ruler seek into the new gap paints actual black preview pixels");
    } else check(FALSE, "shared gap has valid bounds");
    key(window, GDK_KEY_z, GDK_CONTROL_MASK); check(settled(window, 3), "Ctrl+Z restores the linked edit through the root session");
    double before = 0, after = 0;
    point(window, second, &x, &y, &before); key(window, GDK_KEY_plus, GDK_CONTROL_MASK);
    point(window, second, &x, &y, &after);
    check(after > before && revision(window) == 3, "Ctrl+plus zooms the shared timeline without changing the project");
    key(window, GDK_KEY_0, GDK_CONTROL_MASK);
    check(mc_linux_video_editor_command(window, "{\"expectedRevision\":3,\"requestId\":\"gtk-window-undo\",\"op\":{\"type\":\"undo\"}}") && settled(window, 4),
        "automation uses the same authoritative edit and media lane");
    check(seek(window, 1000) && wait_pixels(window, image, FALSE), "preview still renders source pixels after edit and undo");
    gboolean blocked = g_rename(draft, backup) == 0 && g_mkdir(draft, 0700) == 0;
    check(blocked, "prepare an actual unwriteable draft destination while retaining its saved bytes");
    if (!blocked) goto done;
    check(mc_linux_video_editor_command(window, "{\"expectedRevision\":4,\"requestId\":\"gtk-save-veto\",\"op\":{\"type\":\"mute\",\"muted\":true}}"),
        "editing queues a real filesystem save before close");
    check(!mc_linux_video_editors_close() && wait_veto(), "save failure revokes closing so the app can cancel quit");
    check(g_rmdir(draft) == 0 && g_rename(backup, draft) == 0, "restore the same saved draft after filesystem failure");
    check(retry_error(window) && settled(window, 5), "native Retry saves the retained edit without losing the window");
    gtk_window_close(GTK_WINDOW(window)); pump(1);
    check(wait_closed(), "window close waits for actual draft and media drain");
    g_object_unref(window); window = NULL;
    window = mc_linux_video_editor_open_test(application, argv[1], draft, TRUE);
    if (window) g_object_ref(window);
    check(window && settled(window, 5), "reopening restores the saved v2 document revision");
    if (window) {
        check(click(window, "export"), "shared export opens a pending native chooser"); pump(150);
        check(!mc_linux_video_editors_close() && wait_closed(), "close dismisses chooser before draining the shared owner");
        g_object_unref(window); window = NULL;
    }
    window = mc_linux_video_editor_open_test(application, argv[1], draft, TRUE);
    if (window) g_object_ref(window);
    if (window && settled(window, 5)) {
        check(click(window, "export"), "shared export queues its chooser before the next GTK tick");
        check(!mc_linux_video_editors_close() && wait_closed(), "immediate close also cancels an unpresented chooser ticket");
        g_object_unref(window); window = NULL;
    } else { check(FALSE, "reopen before unpresented chooser regression"); goto done; }
    // GTK/application teardown can bypass delete-event. This must still drain
    // the original owner without its polling timer dereferencing freed widgets.
    window = mc_linux_video_editor_open_test(application, argv[1], draft, TRUE);
    if (window) { g_object_ref(window); gtk_widget_destroy(window); }
    check(window && wait_closed(), "direct toolkit destruction during open safely drains asynchronous ownership");
done:
    if (g_file_test(backup, G_FILE_TEST_EXISTS)) {
        if (g_file_test(draft, G_FILE_TEST_IS_DIR)) g_rmdir(draft);
        if (!g_file_test(draft, G_FILE_TEST_EXISTS)) g_rename(backup, draft);
        if (window) retry_error(window);
    }
    mc_linux_video_editors_close(); check(wait_closed(), "all editor workers and windows close");
    if (window) g_object_unref(window);
    char *final = hash(argv[1]); check(original && !g_strcmp0(original, final), "all edits and closes leave source bytes unchanged");
    check(criticals == 0, "no GTK or GObject lifecycle criticals");
    for (size_t i = 0; i < G_N_ELEMENTS(domains); i++) g_log_remove_handler(domains[i], handlers[i]);
    g_free(final); g_free(original); g_free(second); g_free(gap); g_free(draft); g_free(image); g_free(gap_image); g_free(backup);
    g_object_unref(application);
    printf("linux-video-editor: %d failure(s)\n", failures); return failures ? 1 : 0;
}
